/* DAWAH X — ahmad, অধ্যায় 22 · খণ্ড 22 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][22]=[[4201,4201,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَحْوَصِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُفَضِّلُ صَلَاةَ الْجَمِيعِ عَلَى صَلَاةِ الرَّجُلِ وَحْدَهُ خَمْسَةً وَعِشْرِينَ ضِعْفًا كُلُّهَا مِثْلُ صَلَاتِهِ ‏","","",""],[4202,4202,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْمُتَوَشِّمَاتِ ‏ ‏وَالْمُتَنَمِّصَاتِ ‏ ‏وَالْمُتَفَلِّجَاتِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأَحْسَبُهُ قَالَ الْمُغَيِّرَاتِ خَلْقَ اللَّهِ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُ ‏","","",""],[4203,4203,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏بَرَزَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا مَعَهُ فَقَالَ لِي ‏ ‏الْتَمِسْ ‏ ‏لِي ثَلَاثَةَ أَحْجَارٍ قَالَ فَوَجَدْتُ لَهُ حَجَرَيْنِ ‏ ‏وَرَوْثَةً ‏ ‏قَالَ فَأَتَيْتُهُ بِهَا فَأَخَذَ الْحَجَرَيْنِ وَأَلْقَى ‏ ‏الرَّوْثَةَ ‏ ‏وَقَالَ هَذِهِ ‏ ‏رِكْسٌ ‏","","",""],[4204,4204,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَنْتَجِي ‏ ‏اثْنَانِ دُونَ صَاحِبِهِمَا فَإِنَّ ذَلِكَ يُحْزِنُهُ ‏","","",""],[4205,4205,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏خَطَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطًّا بِيَدِهِ ثُمَّ قَالَ هَذَا سَبِيلُ اللَّهِ مُسْتَقِيمًا قَالَ ثُمَّ خَطَّ عَنْ يَمِينِهِ وَشِمَالِهِ ثُمَّ قَالَ هَذِهِ السُّبُلُ وَلَيْسَ مِنْهَا سَبِيلٌ إِلَّا عَلَيْهِ شَيْطَانٌ يَدْعُو إِلَيْهِ ثُمَّ قَرَأَ ‏ { ‏وَإِنَّ هَذَا صِرَاطِي ‏ ‏مُسْتَقِيمًا فَاتَّبِعُوهُ وَلَا تَتَّبِعُوا السُّبُلَ ‏}","","",""],[4206,4206,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ الْحَسَنِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كُدَيْنَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏مَرَّ يَهُودِيٌّ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُحَدِّثُ أَصْحَابَهُ فَقَالَتْ ‏ ‏قُرَيْشٌ ‏ ‏يَا يَهُودِيُّ إِنَّ هَذَا يَزْعُمُ أَنَّهُ نَبِيٌّ فَقَالَ لَأَسْأَلَنَّهُ عَنْ شَيْءٍ لَا يَعْلَمُهُ إِلَّا نَبِيٌّ قَالَ فَجَاءَ حَتَّى جَلَسَ ثُمَّ قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏مِمَّ يُخْلَقُ الْإِنْسَانُ قَالَ يَا يَهُودِيُّ مِنْ كُلٍّ يُخْلَقُ مِنْ ‏ ‏نُطْفَةِ ‏ ‏الرَّجُلِ وَمِنْ ‏ ‏نُطْفَةِ ‏ ‏الْمَرْأَةِ فَأَمَّا ‏ ‏نُطْفَةُ ‏ ‏الرَّجُلِ ‏ ‏فَنُطْفَةٌ ‏ ‏غَلِيظَةٌ مِنْهَا الْعَظْمُ وَالْعَصَبُ وَأَمَّا ‏ ‏نُطْفَةُ ‏ ‏الْمَرْأَةِ ‏ ‏فَنُطْفَةٌ ‏ ‏رَقِيقَةٌ مِنْهَا اللَّحْمُ وَالدَّمُ فَقَامَ الْيَهُودِيُّ فَقَالَ هَكَذَا كَانَ يَقُولُ مَنْ قَبْلَكَ ‏","","",""],[4207,4207,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ يَعْنِي ابْنَ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏يُذَكِّرُ كُلَّ خَمِيسٍ ‏ ‏أَوْ اثْنَيْنِ ‏ ‏الْأَيَّامَ قَالَ فَقُلْنَا ‏ ‏أَوْ فَقِيلَ ‏ ‏يَا ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏إِنَّا لَنُحِبُّ حَدِيثَكَ ‏ ‏وَنَشْتَهِيهِ وَوَدِدْنَا أَنَّكَ تُذَكِّرُنَا كُلَّ يَوْمٍ فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِنَّهُ لَا يَمْنَعُنِي مِنْ ذَاكَ إِلَّا أَنِّي أَكْرَهُ أَنْ أُمِلَّكُمْ وَإِنِّي ‏ ‏لَأَتَخَوَّلُكُمْ ‏ ‏بِالْمَوْعِظَةِ كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَوَّلُنَا ‏","","",""],[4208,4208,"","","‏ ‏حَدَّثَنَا ‏ ‏نَصْرُ بْنُ بَابٍ ‏ ‏عَنْ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَأَلَ مَسْأَلَةً وَهُوَ عَنْهَا غَنِيٌّ جَاءَتْ يَوْمَ الْقِيَامَةِ ‏ ‏كُدُوحًا ‏ ‏فِي وَجْهِهِ وَلَا تَحِلُّ ‏ ‏الصَّدَقَةُ ‏ ‏لِمَنْ لَهُ خَمْسُونَ دِرْهَمًا أَوْ عِوَضُهَا مِنْ الذَّهَبِ ‏","","",""],[4209,4209,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ مَرْثَدٍ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ بْنِ عَبْدِ اللَّهِ الْيَشْكُرِيِّ ‏ ‏عَنِ ‏ ‏الْمَعْرُورِ بْنِ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَالَتْ ‏ ‏أُمُّ حَبِيبَةَ ‏ ‏اللَّهُمَّ مَتِّعْنِي بِزَوْجِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِأَبِي ‏ ‏أَبِي سُفْيَانَ ‏ ‏وَبِأَخِي ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكِ سَأَلْتِ اللَّهَ لِآجَالٍ مَضْرُوبَةٍ وَأَرْزَاقٍ مَقْسُومَةٍ وَآثَارٍ مَبْلُوغَةٍ لَا يُعَجَّلُ مِنْهَا شَيْءٌ قَبْلَ ‏ ‏حِلِّهِ ‏ ‏وَلَا يُؤَخَّرُ مِنْهَا شَيْءٌ بَعْدَ ‏ ‏حِلِّهِ ‏ ‏وَلَوْ سَأَلْتِ اللَّهَ أَنْ يُعَافِيَكِ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ كَانَ خَيْرًا لَكِ ‏","","",""],[4210,4210,"","","‏ ‏قَالَ ‏ ‏فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ الْقِرَدَةُ وَالْخَنَازِيرُ هِيَ مِمَّا مُسِخَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَمْ يَمْسَخْ قَوْمًا أَوْ يُهْلِكْ قَوْمًا فَيَجْعَلَ لَهُمْ نَسْلًا وَلَا عَاقِبَةً وَإِنَّ الْقِرَدَةَ وَالْخَنَازِيرَ قَدْ كَانَتْ قَبْلَ ذَلِكَ ‏","","",""],[4211,4211,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى أَبِي ‏ ‏مِنْ هَاهُنَا فَأَقَرَّ بِهِ ‏ ‏وَقَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِدْرِيسَ الشَّافِعِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدُ بْنُ سَالِمٍ يَعْنِي الْقَدَّاحَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَنَّ ‏ ‏إِسْمَاعِيلَ بْنَ أُمَيَّةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏حَضَرْتُ ‏ ‏أَبَا عُبَيْدَةَ بْنَ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏وَأَتَاهُ رَجُلَانِ يَتَبَايَعَانِ سِلْعَةً فَقَالَ هَذَا أَخَذْتُ بِكَذَا وَكَذَا وَقَالَ هَذَا بِعْتُ بِكَذَا وَكَذَا ‏ ‏فَقَالَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏أُتِيَ ‏ ‏عَبْدُ اللَّهِ بْنُ مَسْعُودٍ ‏ ‏فِي مِثْلِ هَذَا فَقَالَ حَضَرْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ فِي مِثْلِ هَذَا ‏ ‏فَأَمَرَ بِالْبَائِعِ أَنْ يُسْتَحْلَفَ ثُمَّ يُخَيَّرَ ‏ ‏الْمُبْتَاعُ ‏ ‏إِنْ شَاءَ أَخَذَ وَإِنْ شَاءَ تَرَكَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى أَبِي ‏ ‏قَالَ أُخْبِرْتُ عَنْ ‏ ‏هِشَامِ بْنِ يُوسُفَ ‏ ‏فِي الْبَيِّعَيْنِ فِي حَدِيثِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُبَيْدٍ ‏ ‏و قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏حَجَّاجٌ الْأَعْوَرُ ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُبَيْدَةَ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ أَبِي لَيْلَى ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏وَلَيْسَ فِيهِ عَنْ أَبِيهِ ‏","","",""],[4212,4212,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَوْنُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا اخْتَلَفَ الْبَيِّعَانِ فَالْقَوْلُ مَا قَالَ الْبَائِعُ ‏ ‏وَالْمُبْتَاعُ ‏ ‏بِالْخِيَارِ ‏","","",""],[4213,4213,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى أَبِي ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْمَسْعُودِيِّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَسْعُودٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اخْتَلَفَ الْبَيِّعَانِ وَلَيْسَ بَيْنَهُمَا ‏ ‏بَيِّنَةٌ ‏ ‏فَالْقَوْلُ مَا يَقُولُ صَاحِبُ السِّلْعَةِ أَوْ ‏ ‏يَتَرَادَّانِ ‏","","",""],[4214,4214,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى أَبِي ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَعْنٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا اخْتَلَفَ الْبَيِّعَانِ وَالسِّلْعَةُ كَمَا هِيَ فَالْقَوْلُ مَا قَالَ الْبَائِعُ أَوْ ‏ ‏يَتَرَادَّانِ ‏","","",""],[4215,4215,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعْدٍ أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَعْنٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏قَالَ ‏ ‏اخْتَلَفَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَالْأَشْعَثُ ‏ ‏فَقَالَ ذَا بِعَشَرَةٍ وَقَالَ ذَا بِعِشْرِينَ قَالَ اجْعَلْ بَيْنِي وَبَيْنَكَ رَجُلًا قَالَ أَنْتَ بَيْنِي وَبَيْنَ نَفْسِكَ قَالَ أَقْضِي بِمَا ‏ ‏قَضَى ‏ ‏بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اخْتَلَفَ الْبَيِّعَانِ وَلَمْ تَكُنْ بَيِّنَةٌ فَالْقَوْلُ قَوْلُ الْبَائِعِ أَوْ ‏ ‏يَتَرَادَّانِ ‏ ‏الْبَيْعَ ‏","","",""],[4216,4216,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏مِنْ كِتَابِهِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمُ بْنُ بَشِيرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏وَأَبُو مُعَاوِيَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏لِلْفَرَسِ ‏ ‏سَهْمَيْنِ ‏ ‏وَلِلرَّجُلِ سَهْمًا ‏ ‏وَقَالَ ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏أَسْهَمَ ‏ ‏لِلرَّجُلِ وَلِفَرَسِهِ ثَلَاثَةَ ‏ ‏أَسْهُمٍ ‏ ‏سَهْمًا ‏ ‏لَهُ ‏ ‏وَسَهْمَيْنِ ‏ ‏لِفَرَسِهِ ‏","","",""],[4217,4217,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَجُلًا جَاءَ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَسَأَلَهُ فَقَالَ إِنَّهُ ‏ ‏نَذَرَ ‏ ‏أَنْ يَصُومَ كُلَّ يَوْمِ أَرْبِعَاءَ فَأَتَى ذَلِكَ عَلَى يَوْمِ أَضْحًى ‏ ‏أَوْ فِطْرٍ ‏ ‏فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَمَرَ اللَّهُ بِوَفَاءِ ‏ ‏النَّذْرِ ‏ ‏وَنَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَوْمِ ‏ ‏يَوْمِ النَّحْرِ ‏","","",""],[4218,4218,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا ‏ ‏يَتَنَاجَ ‏ ‏اثْنَانِ دُونَ وَاحِدٍ ‏","","",""],[4219,4219,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَعْتَقَ نَصِيبًا لَهُ فِي مَمْلُوكٍ كُلِّفَ أَنْ يُتِمَّ عِتْقَهُ بِقِيمَةِ ‏ ‏عَدْلٍ ‏","","",""],[4220,4220,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏حَيْثُ ‏ ‏أَفَاضَ ‏ ‏مِنْ ‏ ‏عَرَفَاتٍ ‏ ‏إِلَى ‏ ‏جَمْعٍ ‏ ‏فَصَلَّى بِنَا الْمَغْرِبَ وَمَضَى ثُمَّ قَالَ الصَّلَاةَ فَصَلَّى رَكْعَتَيْنِ ثُمَّ قَالَ هَكَذَا فَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْمَكَانِ كَمَا فَعَلْتُ ‏","","",""],[4221,4221,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ الْجُرَشِيِّ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّهُ مَرَّ ‏ ‏بِأَبِي هُرَيْرَةَ ‏ ‏وَهُوَ يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ تَبِعَ جَنَازَةً فَصَلَّى عَلَيْهَا فَلَهُ قِيرَاطٌ فَإِنْ شَهِدَ دَفْنَهَا فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏الْقِيرَاطُ ‏ ‏أَعْظَمُ مِنْ ‏ ‏أُحُدٍ ‏ ‏فَقَالَ لَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏انْظُرْ مَا تُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ إِلَيْهِ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏حَتَّى انْطَلَقَ بِهِ إِلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَ لَهَا يَا ‏ ‏أُمَّ الْمُؤْمِنِينَ ‏ ‏أَنْشُدُكِ ‏ ‏بِاللَّهِ أَسَمِعْتِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ مَنْ تَبِعَ جَنَازَةً فَصَلَّى عَلَيْهَا فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏فَإِنْ شَهِدَ دَفْنَهَا فَلَهُ ‏ ‏قِيرَاطَانِ ‏ ‏فَقَالَتْ اللَّهُمَّ نَعَمْ فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏إِنَّهُ لَمْ يَكُنْ يَشْغَلُنِي عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَرْسُ ‏ ‏الْوَدِيِّ ‏ ‏وَلَا ‏ ‏صَفْقٌ ‏ ‏بِالْأَسْوَاقِ إِنِّي إِنَّمَا كُنْتُ أَطْلُبُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَلِمَةً يُعَلِّمُنِيهَا وَأُكْلَةً يُطْعِمُنِيهَا فَقَالَ لَهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنْتَ يَا ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏كُنْتَ أَلْزَمَنَا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَعْلَمَنَا بِحَدِيثِهِ ‏","","",""],[4222,4222,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا لَمْ يَجِدْ ‏ ‏الْمُحْرِمُ ‏ ‏النَّعْلَيْنِ فَلْيَلْبَسْ الْخُفَّيْنِ وَلْيَقْطَعْهُمَا أَسْفَلَ مِنْ ‏ ‏الْكَعْبَيْنِ ‏","","",""],[4223,4223,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَعُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏وَابْنُ عَوْنٍ ‏ ‏وَغَيْرُ وَاحِدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَيْنَ يُحْرِمُ قَالَ ‏ ‏مُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏الشَّامِ ‏ ‏مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏ ‏وَمُهَلُّ ‏ ‏أَهْلِ ‏ ‏نَجْدٍ ‏ ‏مِنْ ‏ ‏قَرْنٍ ‏ ‏و قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَقَاسَ النَّاسُ ذَاتَ عِرْقٍ ‏ ‏بِقَرْنٍ ‏","","",""],[4224,4224,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا لَمْ يَجِدْ ‏ ‏الْمُحْرِمُ ‏ ‏النَّعْلَيْنِ فَلْيَلْبَسْ الْخُفَّيْنِ وَلْيَقْطَعْهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ ‏","","",""],[4225,4225,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَتْ تَلْبِيَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏ ‏وَزَادَ فِيهَا ‏ ‏ابْنُ عُمَرَ ‏ ‏لَبَّيْكَ لَبَّيْكَ وَسَعْدَيْكَ وَالْخَيْرُ فِي يَدَيْكَ لَبَّيْكَ ‏ ‏وَالرَّغْبَاءُ ‏ ‏إِلَيْكَ وَالْعَمَلُ ‏","","",""],[4226,4226,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏غَدَوْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏عَرَفَاتٍ ‏ ‏مِنَّا الْمُكَبِّرُ وَمِنَّا الْمُلَبِّي ‏","","",""],[4227,4227,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏أَخْبَرَنِي ‏ ‏زِيَادُ بْنُ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏بِمِنًى ‏ ‏فَمَرَّ بِرَجُلٍ وَهُوَ ‏ ‏يَنْحَرُ ‏ ‏بَدَنَةً ‏ ‏وَهِيَ بَارِكَةٌ فَقَالَ ‏ ‏ابْعَثْهَا قِيَامًا مُقَيَّدَةً سُنَّةَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4228,4228,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏حَيْثُ ‏ ‏أَفَاضَ ‏ ‏مِنْ ‏ ‏عَرَفَاتٍ ‏ ‏ثُمَّ أَتَى ‏ ‏جَمْعًا ‏ ‏فَصَلَّى الْمَغْرِبَ وَالْعِشَاءَ فَلَمَّا فَرَغَ قَالَ فَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْمَكَانِ مِثْلَ مَا فَعَلْتُ ‏ ‏قَالَ ‏ ‏هُشَيْمٌ ‏ ‏مَرَّةً فَصَلَّى بِنَا الْمَغْرِبَ ثُمَّ قَالَ الصَّلَاةَ وَصَلَّى رَكْعَتَيْنِ ثُمَّ قَالَ هَكَذَا فَعَلَ بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْمَكَانِ ‏","","",""],[4229,4229,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَعُبَيْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏وَابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ مَا يَقْتُلُ ‏ ‏الْمُحْرِمُ ‏ ‏قَالَ ‏ ‏يَقْتُلُ الْعَقْرَبَ ‏ ‏وَالْفُوَيْسِقَةَ ‏ ‏وَالْحِدَأَةَ وَالْغُرَابَ وَالْكَلْبَ ‏ ‏الْعَقُورَ ‏","","",""],[4230,4230,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ أَبَاهُ يَقُولُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏مَا لِي لَا أَرَاكَ ‏ ‏تَسْتَلِمُ ‏ ‏إِلَّا هَذَيْنِ الرُّكْنَيْنِ الْحَجَرَ الْأَسْوَدَ وَالرُّكْنَ ‏ ‏الْيَمَانِيَ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِنْ أَفْعَلْ فَقَدْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏اسْتِلَامَهُمَا ‏ ‏يَحُطُّ ‏ ‏الْخَطَايَا ‏","","",""],[4231,4231,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُهُ يَقُولُ ‏ ‏مَنْ طَافَ أُسْبُوعًا ‏ ‏يُحْصِيهِ ‏ ‏وَصَلَّى رَكْعَتَيْنِ كَانَ لَهُ كَعِدْلِ رَقَبَةٍ ‏","","",""],[4232,4232,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُهُ يَقُولُ ‏ ‏مَا رَفَعَ رَجُلٌ قَدَمًا وَلَا وَضَعَهَا إِلَّا كُتِبَتْ لَهُ عَشْرُ حَسَنَاتٍ ‏ ‏وَحُطَّ ‏ ‏عَنْهُ عَشْرُ سَيِّئَاتٍ وَرُفِعَ لَهُ عَشْرُ دَرَجَاتٍ ‏","","",""],[4233,4233,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَسْتَلِمُ ‏ ‏الْحَجَرَ الْأَسْوَدَ فَلَا أَدَعُ ‏ ‏اسْتِلَامَهُ ‏ ‏فِي شِدَّةٍ وَلَا رَخَاءٍ ‏","","",""],[4234,4234,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏غَيْرُ وَاحِدٍ ‏ ‏وَابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيْتَ ‏ ‏وَمَعَهُ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏وَأُسَامَةُ بْنُ زَيْدٍ ‏ ‏وَعُثْمَانُ بْنُ طَلْحَةَ ‏ ‏وَبِلَالٌ ‏ ‏فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَجَافَ ‏ ‏عَلَيْهِمْ الْبَابَ فَمَكَثَ فِيهِ مَا شَاءَ اللَّهُ ثُمَّ خَرَجَ فَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَكَانَ أَوَّلُ مَنْ لَقِيتُ مِنْهُمْ ‏ ‏بِلَالًا ‏ ‏فَقُلْتُ أَيْنَ صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هَاهُنَا بَيْنَ الْأُسْطُوَانَتَيْنِ ‏","","",""],[4235,4235,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الْقَرْعِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏أَنْ ‏ ‏يُنْتَبَذَ ‏ ‏فِيهِمَا ‏","","",""],[4236,4236,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ أَحَدُكُمْ إِلَى الْجُمُعَةِ فَلْيَغْتَسِلْ ‏","","",""],[4237,4237,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَمَلَ عَلَيْنَا السِّلَاحَ فَلَيْسَ مِنَّا ‏","","",""],[4238,4238,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُعَرِّضُ ‏ ‏عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏وَيُصَلِّي إِلَيْهَا ‏","","",""],[4239,4239,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏سَمِعْتُ ‏ ‏بُرْدًا ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبِيتُ أَحَدٌ ثَلَاثَ لَيَالٍ إِلَّا وَوَصِيَّتُهُ مَكْتُوبَةٌ قَالَ فَمَا بِتُّ مِنْ لَيْلَةٍ بَعْدُ إِلَّا وَوَصِيَّتِي عِنْدِي مَوْضُوعَةٌ ‏","","",""],[4240,4240,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يُصَلِّي عَلَى دَابَّتِهِ التَّطَوُّعَ حَيْثُ تَوَجَّهَتْ بِهِ فَذَكَرْتُ لَهُ ذَلِكَ فَقَالَ رَأَيْتُ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏يَفْعَلُهُ ‏","","",""],[4241,4241,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ تُحْلَبَ مَوَاشِي النَّاسِ إِلَّا بِإِذْنِهِمْ ‏","","",""],[4242,4242,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ الْأَزْرَقُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ يَعْنِي ابْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ يَجْمَعُ بَيْنَ الصَّلَاتَيْنِ الْمَغْرِبِ وَالْعِشَاءِ إِذَا غَابَ ‏ ‏الشَّفَقُ ‏ ‏قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْمَعُ بَيْنَهُمَا إِذَا جَدَّ بِهِ السَّيْرُ ‏","","",""],[4243,4243,"","","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُثْمَانَ يَعْنِي الْغَطَفَانِيَّ ‏ ‏أَخْبَرَنَا ‏ ‏عُمَرُ بْنُ نَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْقَزَعِ ‏ ‏وَالْقَزَعُ أَنْ يُحْلَقَ الصَّبِيُّ فَيُتْرَكَ بَعْضُ شَعَرِهِ ‏","","",""],[4244,4244,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏عَبْدُ الْعَزِيزِ بْنُ مَرْوَانَ ‏ ‏إِلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنْ ارْفَعْ إِلَيَّ حَاجَتَكَ قَالَ فَكَتَبَ إِلَيْهِ ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِنَّ الْيَدَ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى وَابْدَأْ بِمَنْ ‏ ‏تَعُولُ ‏ ‏وَلَسْتُ أَسْأَلُكَ شَيْئًا وَلَا أَرُدُّ رِزْقًا رَزَقَنِيهِ اللَّهُ مِنْكَ ‏","","",""],[4245,4245,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ الصَّمَدِ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُصَوِّرُونَ يُعَذَّبُونَ يَوْمَ الْقِيَامَةِ وَيُقَالُ أَحْيُوا مَا خَلَقْتُمْ ‏","","",""],[4246,4246,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ تَطَوُّعًا فَإِذَا أَرَادَ أَنْ ‏ ‏يَسْجُدَ ‏ ‏نَزَلَ فَأَوْتَرَ عَلَى الْأَرْضِ ‏","","",""],[4247,4247,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِابْنِ عُمَرَ ‏ ‏رَجُلٌ ‏ ‏قَذَفَ ‏ ‏امْرَأَتَهُ فَقَالَ ‏ ‏فَرَّقَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَخَوَيْ ‏ ‏بَنِي الْعَجْلَانِ ‏ ‏وَقَالَ اللَّهُ يَعْلَمُ أَنَّ أَحَدَكُمَا كَاذِبٌ فَهَلْ مِنْكُمَا تَائِبٌ فَأَبَيَا فَرَدَّدَهُمَا ثَلَاثَ مَرَّاتٍ فَأَبَيَا فَفَرَّقَ بَيْنَهُمَا ‏","","",""],[4248,4248,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏نَادَى ‏ ‏ابْنُ عُمَرَ ‏ ‏بِالصَّلَاةِ ‏ ‏بِضَجْنَانَ ‏ ‏ثُمَّ نَادَى أَنْ صَلُّوا فِي ‏ ‏رِحَالِكُمْ ‏ ‏ثُمَّ حَدَّثَ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَأْمُرُ الْمُنَادِيَ فَيُنَادِي بِالصَّلَاةِ ثُمَّ يُنَادِي أَنْ صَلُّوا فِي ‏ ‏رِحَالِكُمْ ‏ ‏فِي اللَّيْلَةِ الْبَارِدَةِ وَفِي اللَّيْلَةِ الْمَطِيرَةِ فِي السَّفَرِ ‏","","",""],[4249,4249,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ اتَّخَذَ ‏ ‏أَوْ قَالَ ‏ ‏اقْتَنَى ‏ ‏كَلْبًا لَيْسَ بِضَارٍ وَلَا كَلْبَ مَاشِيَةٍ نَقَصَ مِنْ أَجْرِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطَانِ ‏ ‏فَقِيلَ لَهُ إِنَّ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏يَقُولُ وَكَلْبَ ‏ ‏حَرْثٍ ‏ ‏فَقَالَ أَنَّى ‏ ‏لِأَبِي هُرَيْرَةَ ‏ ‏حَرْثٌ ‏","","",""],[4250,4250,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏دَخَلَ عَلَيْهِ ابْنُهُ ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ ‏ ‏وَظَهْرُهُ فِي الدَّارِ فَقَالَ إِنِّي لَا آمَنُ أَنْ يَكُونَ الْعَامَ بَيْنَ النَّاسِ قِتَالٌ فَتُصَدَّ عَنْ ‏ ‏الْبَيْتِ ‏ ‏فَلَوْ أَقَمْتَ فَقَالَ قَدْ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَالَ كُفَّارُ ‏ ‏قُرَيْشٍ ‏ ‏بَيْنَهُ وَبَيْنَ ‏ ‏الْبَيْتِ ‏ ‏فَإِنْ ‏ ‏يُحَلْ ‏ ‏بَيْنِي وَبَيْنَهُ أَفْعَلْ كَمَا فَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ { ‏لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ‏} ‏قَالَ إِنِّي قَدْ ‏ ‏أَوْجَبْتُ ‏ ‏عُمْرَةً ثُمَّ سَارَ حَتَّى إِذَا كَانَ ‏ ‏بِالْبَيْدَاءِ ‏ ‏قَالَ مَا أَرَى أَمْرَهُمَا إِلَّا وَاحِدًا أُشْهِدُكُمْ أَنِّي قَدْ ‏ ‏أَوْجَبْتُ ‏ ‏مَعَ عُمْرَتِي حَجًّا ثُمَّ قَدِمَ فَطَافَ لَهُمَا طَوَافًا وَاحِدًا ‏","","",""],[4251,4251,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ الرِّجَالَ وَالنِّسَاءَ يَتَوَضَّئُونَ عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمِيعًا مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[4252,4252,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ مَا يَلْبَسُ ‏ ‏الْمُحْرِمُ ‏ ‏أَوْ قَالَ مَا يَتْرُكُ ‏ ‏الْمُحْرِمُ ‏ ‏فَقَالَ ‏ ‏لَا يَلْبَسُ الْقَمِيصَ وَلَا السَّرَاوِيلَ وَلَا الْعِمَامَةَ وَلَا الْخُفَّيْنِ إِلَّا أَنْ لَا يَجِدَ نَعْلَيْنِ فَمَنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْهُمَا أَسْفَلَ مِنْ الْكَعْبَيْنِ وَلَا ‏ ‏الْبُرْنُسَ ‏ ‏وَلَا شَيْئًا مِنْ الثِّيَابِ ‏ ‏مَسَّهُ ‏ ‏وَرْسٌ ‏ ‏وَلَا ‏ ‏زَعْفَرَانٌ ‏","","",""],[4253,4253,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏فِي ‏ ‏عَاشُورَاءَ ‏ ‏صَامَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَمَرَ بِصَوْمِهِ فَلَمَّا فُرِضَ رَمَضَانُ تُرِكَ فَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏لَا يَصُومُهُ إِلَّا أَنْ يَأْتِيَ عَلَى صَوْمِهِ ‏","","",""],[4254,4254,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏حَتَّى يَتَفَرَّقَا أَوْ يَكُونَ بَيْعَ ‏ ‏خِيَارٍ ‏ ‏قَالَ وَرُبَّمَا قَالَ ‏ ‏نَافِعٌ ‏ ‏أَوْ يَقُولَ أَحَدُهُمَا لِلْآخَرِ اخْتَرْ ‏","","",""],[4255,4255,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ يُحَدِّثُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَزُورُهُ رَاكِبًا وَمَاشِيًا ‏ ‏يَعْنِي ‏ ‏مَسْجِدَ قُبَاءَ ‏","","",""],[4256,4256,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏فَرَضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَةَ ‏ ‏رَمَضَانَ عَلَى الذَّكَرِ وَالْأُنْثَى وَالْحُرِّ وَالْمَمْلُوكِ ‏ ‏صَاعَ ‏ ‏تَمْرٍ أَوْ ‏ ‏صَاعَ ‏ ‏شَعِيرٍ ‏ ‏قَالَ ‏ ‏فَعَدَلَ ‏ ‏النَّاسُ بِهِ بَعْدُ نِصْفَ ‏ ‏صَاعِ ‏ ‏بُرٍّ ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏وَقَالَ ‏ ‏نَافِعٌ ‏ ‏كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يُعْطِي التَّمْرَ إِلَّا عَامًا وَاحِدًا ‏ ‏أَعْوَزَ ‏ ‏التَّمْرُ فَأَعْطَى الشَّعِيرَ ‏","","",""],[4257,4257,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَبَّقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ الْخَيْلِ فَأَرْسَلَ مَا ‏ ‏ضُمِّرَ ‏ ‏مِنْهَا مِنْ ‏ ‏الْحَفْيَاءِ ‏ ‏أَوْ ‏ ‏الحَيْفَاءِ ‏ ‏إِلَى ‏ ‏ثَنِيَّةِ الْوَدَاعِ ‏ ‏وَأَرْسَلَ مَا لَمْ ‏ ‏يُضَمَّرْ ‏ ‏مِنْهَا مِنْ ‏ ‏ثَنِيَّةِ الْوَدَاعِ ‏ ‏إِلَى مَسْجِدِ ‏ ‏بَنِي زُرَيْقٍ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَكُنْتُ فَارِسًا يَوْمَئِذٍ فَسَبَقْتُ النَّاسَ ‏ ‏طَفَّفَ ‏ ‏بِيَ الْفَرَسُ مَسْجِدَ ‏ ‏بَنِي زُرَيْقٍ ‏","","",""],[4258,4258,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا الشَّهْرُ تِسْعٌ وَعِشْرُونَ فَلَا تَصُومُوا حَتَّى تَرَوْهُ وَلَا تُفْطِرُوا حَتَّى تَرَوْهُ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَاقْدُرُوا لَهُ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏فَكَانَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏إِذَا مَضَى مِنْ شَعْبَانَ تِسْعٌ وَعِشْرُونَ يَبْعَثُ مَنْ يَنْظُرُ فَإِنْ رُئِيَ فَذَاكَ وَإِنْ لَمْ يُرَ وَلَمْ ‏ ‏يَحُلْ ‏ ‏دُونَ مَنْظَرِهِ سَحَابٌ وَلَا ‏ ‏قَتَرٌ ‏ ‏أَصْبَحَ مُفْطِرًا وَإِنْ ‏ ‏حَالَ ‏ ‏دُونَ مَنْظَرِهِ سَحَابٌ أَوْ ‏ ‏قَتَرٌ ‏ ‏أَصْبَحَ صَائِمًا ‏","","",""],[4259,4259,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الَّذِي يَجُرُّ ثَوْبَهُ مِنْ ‏ ‏الْخُيَلَاءِ ‏ ‏لَا يَنْظُرُ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏نَافِعٌ ‏ ‏فَأُنْبِئْتُ ‏ ‏أَنَّ ‏ ‏أُمَّ سَلَمَةَ ‏ ‏قَالَتْ فَكَيْفَ بِنَا قَالَ شِبْرًا قَالَتْ إِذَنْ تَبْدُوَ أَقْدَامُنَا قَالَ ذِرَاعًا لَا تَزِدْنَ عَلَيْهِ ‏","","",""],[4260,4260,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الْمُزَابَنَةِ ‏ ‏وَالْمُزَابَنَةُ أَنْ يُبَاعَ مَا فِي رُءُوسِ النَّخْلِ بِتَمْرٍ بِكَيْلٍ مُسَمًّى إِنْ زَادَ فَلِي وَإِنْ نَقَصَ فَعَلَيَّ ‏","","",""],[4261,4261,"","","‏ ‏قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي بَيْعِ ‏ ‏الْعَرَايَا ‏ ‏بِخَرْصِهَا ‏","","",""],[4262,4262,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ ‏ ‏حَبَلِ الْحَبَلَةِ ‏","","",""],[4263,4263,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ كَيْفَ تَأْمُرُنَا أَنْ نُصَلِّيَ مِنْ اللَّيْلِ قَالَ ‏ ‏يُصَلِّي أَحَدُكُمْ مَثْنَى مَثْنَى فَإِذَا خَشِيَ الصُّبْحَ صَلَّى وَاحِدَةً فَأَوْتَرَتْ لَهُ مَا قَدْ صَلَّى مِنْ اللَّيْلِ ‏","","",""],[4264,4264,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ النَّخْلِ حَتَّى ‏ ‏يَزْهُوَ ‏ ‏وَعَنْ ‏ ‏السُّنْبُلِ ‏ ‏حَتَّى يَبْيَضَّ وَيَأْمَنَ ‏ ‏الْعَاهَةَ ‏ ‏نَهَى الْبَائِعَ وَالْمُشْتَرِيَ ‏","","",""],[4265,4265,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏رَأَيْتُ فِي الْمَنَامِ كَأَنَّ بِيَدِي قِطْعَةَ ‏ ‏إِسْتَبْرَقٍ ‏ ‏وَلَا أُشِيرُ بِهَا إِلَى مَكَانٍ مِنْ الْجَنَّةِ إِلَّا طَارَتْ بِي إِلَيْهِ فَقَصَّتْهَا ‏ ‏حَفْصَةُ ‏ ‏عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّ أَخَاكِ رَجُلٌ صَالِحٌ ‏ ‏أَوْ إِنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏رَجُلٌ صَالِحٌ ‏","","",""],[4266,4266,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ فَالْأَمِيرُ الَّذِي عَلَى النَّاسِ رَاعٍ وَهُوَ مَسْئُولٌ عَنْ رَعِيَّتِهِ وَالرَّجُلُ رَاعٍ عَلَى أَهْلِ بَيْتِهِ وَهُوَ مَسْئُولٌ وَالْمَرْأَةُ رَاعِيَةٌ عَلَى بَيْتِ زَوْجِهَا وَهِيَ مَسْئُولَةٌ وَالْعَبْدُ رَاعٍ عَلَى مَالِ سَيِّدِهِ وَهُوَ مَسْئُولٌ أَلَا فَكُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ ‏","","",""],[4267,4267,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏قَفَلَ ‏ ‏مِنْ حَجٍّ أَوْ غَزْوٍ فَعَلَا ‏ ‏فَدْفَدًا ‏ ‏مِنْ الْأَرْضِ أَوْ ‏ ‏شَرَفًا ‏ ‏قَالَ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏ ‏آيِبُونَ ‏ ‏تَائِبُونَ سَاجِدُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ صَدَقَ اللَّهُ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ ‏","","",""],[4268,4268,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَدْ أُتِيَ بِهِ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْنِي الضَّبَّ ‏ ‏فَلَمْ يَأْكُلْهُ وَلَمْ يُحَرِّمْهُ ‏","","",""],[4269,4269,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏الْيَهُودَ ‏ ‏أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجُلٍ وَامْرَأَةٍ مِنْهُمْ قَدْ زَنَيَا فَقَالَ ‏ ‏مَا تَجِدُونَ فِي كِتَابِكُمْ فَقَالُوا ‏ ‏نُسَخِّمُ ‏ ‏وُجُوهَهُمَا وَيُخْزَيَانِ فَقَالَ كَذَبْتُمْ إِنَّ فِيهَا ‏ ‏الرَّجْمَ ‏ ‏فَأْتُوا بِالتَّوْرَاةِ فَاتْلُوهَا إِنْ كُنْتُمْ صَادِقِينَ فَجَاءُوا بِالتَّوْرَاةِ وَجَاءُوا بِقَارِئٍ لَهُمْ أَعْوَرَ يُقَالُ لَهُ ‏ ‏ابْنُ صُورِيَا ‏ ‏فَقَرَأَ حَتَّى إِذَا انْتَهَى إِلَى مَوْضِعٍ مِنْهَا وَضَعَ يَدَهُ عَلَيْهِ فَقِيلَ لَهُ ارْفَعْ يَدَكَ فَرَفَعَ يَدَهُ فَإِذَا هِيَ ‏ ‏تَلُوحُ ‏ ‏فَقَالَ ‏ ‏أَوْ قَالُوا ‏ ‏يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنَّ فِيهَا ‏ ‏الرَّجْمَ ‏ ‏وَلَكِنَّا كُنَّا نَتَكَاتَمُهُ بَيْنَنَا فَأَمَرَ بِهِمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرُجِمَا ‏ ‏قَالَ فَلَقَدْ رَأَيْتُهُ ‏ ‏يُجَانِئُ ‏ ‏عَلَيْهَا يَقِيهَا الْحِجَارَةَ بِنَفْسِهِ ‏","","",""],[4270,4270,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ النَّاسُ يَرَوْنَ الرُّؤْيَا فَيَقُصُّونَهَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي ‏ ‏أَوْ قَالَ ‏ ‏أَسْمَعُ ‏ ‏رُؤْيَاكُمْ ‏ ‏قَدْ ‏ ‏تَوَاطَأَتْ ‏ ‏عَلَى السَّبْعِ الْأَوَاخِرِ فَمَنْ كَانَ مِنْكُمْ ‏ ‏مُتَحَرِّيَهَا ‏ ‏فَلْيَتَحَرَّهَا ‏ ‏فِي السَّبْعِ الْأَوَاخِرِ ‏","","",""],[4271,4271,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏طَلَّقَ امْرَأَتَهُ تَطْلِيقَةً وَهِيَ حَائِضٌ فَسَأَلَ ‏ ‏عُمَرُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُ أَنْ يَرْجِعَهَا ثُمَّ يُمْهِلَهَا حَتَّى تَحِيضَ حَيْضَةً أُخْرَى ثُمَّ يُمْهِلَهَا حَتَّى تَطْهُرَ ثُمَّ يُطَلِّقَهَا قَبْلَ أَنْ يَمَسَّهَا قَالَ وَتِلْكَ الْعِدَّةُ الَّتِي أَمَرَ اللَّهُ عَزَّ وَجَلَّ أَنْ يُطَلَّقَ لَهَا النِّسَاءُ فَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِذَا سُئِلَ عَنْ الرَّجُلِ يُطَلِّقُ امْرَأَتَهُ وَهِيَ حَائِضٌ فَيَقُولُ أَمَّا أَنَا فَطَلَّقْتُهَا وَاحِدَةً أَوْ اثْنَتَيْنِ ثُمَّ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَهُ أَنْ يُرْجِعَهَا ثُمَّ يُمْهِلَهَا حَتَّى تَحِيضَ حَيْضَةً أُخْرَى ثُمَّ يُمْهِلَهَا حَتَّى تَطْهُرَ ثُمَّ يُطَلِّقَهَا قَبْلَ أَنْ يَمَسَّهَا وَأَمَّا أَنْتَ طَلَّقْتَهَا ثَلَاثًا فَقَدْ عَصَيْتَ اللَّهَ بِمَا أَمَرَكَ بِهِ مِنْ طَلَاقِ امْرَأَتِكَ وَبَانَتْ مِنْكَ ‏","","",""],[4272,4272,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏رَفَعَهُ قَالَ ‏ ‏إِنَّ الْيَدَيْنِ يَسْجُدَانِ كَمَا يَسْجُدُ الْوَجْهُ فَإِذَا وَضَعَ أَحَدُكُمْ وَجْهَهُ فَلْيَضَعْ يَدَيْهِ وَإِذَا رَفَعَهُ فَلْيَرْفَعْهُمَا ‏","","",""],[4273,4273,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ بَاعَ نَخْلًا قَدْ ‏ ‏أُبِّرَتْ ‏ ‏فَثَمَرَتُهَا لِلْبَائِعِ إِلَّا أَنْ يَشْتَرِطَ الْمُبْتَاعُ ‏","","",""],[4274,4274,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطَعَ فِي ‏ ‏مِجَنٍّ ‏ ‏ثَمَنُهُ ثَلَاثَةُ دَرَاهِمَ ‏","","",""],[4275,4275,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَدْ عَلِمْتُ أَنَّ الْأَرْضَ كَانَتْ ‏ ‏تُكْرَى ‏ ‏عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمَا عَلَى ‏ ‏الْأَرْبِعَاءِ ‏ ‏وَشَيْءٍ مِنْ التِّبْنِ لَا أَدْرِي كَمْ هُوَ وَإِنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يُكْرِي ‏ ‏أَرْضَهُ فِي ‏ ‏عَهْدِ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعَهْدِ ‏ ‏عُمَرَ ‏ ‏وَعَهْدِ ‏ ‏عُثْمَانَ ‏ ‏وَصَدْرِ ‏ ‏إِمَارَةِ ‏ ‏مُعَاوِيَةَ ‏ ‏حَتَّى إِذَا كَانَ فِي آخِرِهَا بَلَغَهُ أَنَّ ‏ ‏رَافِعًا ‏ ‏يُحَدِّثُ فِي ذَلِكَ بِنَهْيِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَاهُ وَأَنَا مَعَهُ فَسَأَلَهُ فَقَالَ نَعَمْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏كِرَاءِ ‏ ‏الْمَزَارِعِ فَتَرَكَهَا ‏ ‏ابْنُ عُمَرَ ‏ ‏فَكَانَ لَا ‏ ‏يُكْرِيهَا ‏ ‏فَكَانَ إِذَا سُئِلَ يَقُولُ زَعَمَ ‏ ‏ابْنُ خَدِيجٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏كِرَاءِ ‏ ‏الْمَزَارِعِ ‏","","",""],[4276,4276,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا لَا تُحْتَلَبَنَّ مَاشِيَةُ امْرِئٍ إِلَّا بِإِذْنِهِ أَيُحِبُّ أَحَدُكُمْ أَنْ تُؤْتَى مَشْرُبَتُهُ فَيُكْسَرَ بَابُهَا ثُمَّ ‏ ‏يُنْتَثَلَ ‏ ‏مَا فِيهَا فَإِنَّمَا فِي ضُرُوعِ مَوَاشِيهِمْ طَعَامُ أَحَدِهِمْ أَلَا فَلَا تُحْتَلَبَنَّ مَاشِيَةُ امْرِئٍ إِلَّا بِإِذْنِهِ ‏ ‏أَوْ قَالَ بِأَمْرِهِ ‏","","",""],[4277,4277,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكْعَتَيْنِ قَبْلَ الظُّهْرِ وَرَكْعَتَيْنِ بَعْدَهَا وَرَكْعَتَيْنِ بَعْدَ الْمَغْرِبِ فِي بَيْتِهِ وَرَكْعَتَيْنِ بَعْدَ الْعِشَاءِ فِي بَيْتِهِ ‏ ‏قَالَ وَحَدَّثَتْنِي ‏ ‏حَفْصَةُ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ حِينَ يَطْلُعُ الْفَجْرُ ‏ ‏وَيُنَادِي الْمُنَادِي بِالصَّلَاةِ ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏أُرَاهُ قَالَ خَفِيفَتَيْنِ وَرَكْعَتَيْنِ بَعْدَ الْجُمُعَةِ فِي بَيْتِهِ ‏","","",""],[4278,4278,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُسَافِرُوا بِالْقُرْآنِ فَإِنِّي أَخَافُ أَنْ يَنَالَهُ الْعَدُوُّ ‏","","",""],[4279,4279,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَثَلُكُمْ وَمَثَلُ ‏ ‏الْيَهُودِ ‏ ‏وَالنَّصَارَى ‏ ‏كَرَجُلٍ اسْتَعْمَلَ عُمَّالًا فَقَالَ مَنْ يَعْمَلُ مِنْ صَلَاةِ الصُّبْحِ إِلَى نِصْفِ النَّهَارِ عَلَى ‏ ‏قِيرَاطٍ ‏ ‏قِيرَاطٍ ‏ ‏أَلَا فَعَمِلَتْ ‏ ‏الْيَهُودُ ‏ ‏ثُمَّ قَالَ مَنْ يَعْمَلُ لِي مِنْ نِصْفِ النَّهَارِ إِلَى صَلَاةِ الْعَصْرِ عَلَى ‏ ‏قِيرَاطٍ ‏ ‏قِيرَاطٍ ‏ ‏أَلَا فَعَمِلَتْ ‏ ‏النَّصَارَى ‏ ‏ثُمَّ قَالَ مَنْ يَعْمَلُ لِي مِنْ صَلَاةِ الْعَصْرِ إِلَى غُرُوبِ الشَّمْسِ عَلَى ‏ ‏قِيرَاطَيْنِ ‏ ‏قِيرَاطَيْنِ ‏ ‏أَلَا فَأَنْتُمْ الَّذِينَ عَمِلْتُمْ فَغَضِبَ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏قَالُوا نَحْنُ كُنَّا أَكْثَرَ عَمَلًا وَأَقَلَّ عَطَاءً قَالَ هَلْ ظَلَمْتُكُمْ مِنْ حَقِّكُمْ شَيْئًا قَالُوا لَا قَالَ فَإِنَّمَا هُوَ فَضْلِي ‏ ‏أُوتِيهِ مَنْ أَشَاءُ ‏","","",""],[4280,4280,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى ‏ ‏نُخَامَةً ‏ ‏فِي قِبْلَةِ الْمَسْجِدِ فَقَامَ فَحَكَّهَا ‏ ‏أَوْ قَالَ فَحَتَّهَا ‏ ‏بِيَدِهِ ثُمَّ أَقْبَلَ عَلَى النَّاسِ فَتَغَيَّظَ عَلَيْهِمْ وَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قِبَلَ وَجْهِ أَحَدِكُمْ فِي صَلَاتِهِ فَلَا ‏ ‏يَتَنَخَّمَنَّ ‏ ‏أَحَدٌ مِنْكُمْ قِبَلَ وَجْهِهِ فِي صَلَاتِهِ ‏","","",""],[4281,4281,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ فَاسْتَثْنَى فَهُوَ بِالْخِيَارِ إِنْ شَاءَ أَنْ يَمْضِيَ عَلَى يَمِينِهِ وَإِنْ شَاءَ أَنْ يَرْجِعَ غَيْرَ حِنْثٍ ‏ ‏أَوْ قَالَ غَيْرَ حَرَجٍ ‏","","",""],[4282,4282,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلُّوا فِي بُيُوتِكُمْ وَلَا تَتَّخِذُوهَا قُبُورًا ‏ ‏قَالَ أَحْسَبُهُ ذَكَرَهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4283,4283,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏بَيَانٍ ‏ ‏عَنْ ‏ ‏وَبَرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ ‏ ‏لِابْنِ عُمَرَ ‏ ‏أَطُوفُ ‏ ‏بِالْبَيْتِ ‏ ‏وَقَدْ أَحْرَمْتُ بِالْحَجِّ قَالَ وَمَا ‏ ‏بَأْسُ ‏ ‏ذَلِكَ قَالَ إِنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏نَهَى عَنْ ذَلِكَ قَالَ قَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحْرَمَ بِالْحَجِّ وَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏","","",""],[4284,4284,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏الشَّيْبَانِيُّ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ سُحَيْمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْإِقْرَانِ ‏ ‏إِلَّا أَنْ تَسْتَأْذِنَ أَصْحَابَكَ ‏","","",""],[4285,4285,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ يَلْعَقُ أَصَابِعَهُ ثُمَّ يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكَ لَا تَدْرِي فِي أَيِّ طَعَامِكَ تَكُونُ الْبَرَكَةُ ‏","","",""],[4286,4286,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَتْرُكُوا النَّارَ فِي بُيُوتِكُمْ حِينَ تَنَامُونَ ‏","","",""],[4287,4287,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا النَّاسُ كَإِبِلٍ مِائَةٍ لَا يُوجَدُ فِيهَا ‏ ‏رَاحِلَةٌ ‏","","",""],[4288,4288,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُمْ كَانُوا يُضْرَبُونَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اشْتَرَوْا طَعَامًا ‏ ‏جُزَافًا ‏ ‏أَنْ يَبِيعُوهُ فِي مَكَانِهِ حَتَّى ‏ ‏يُؤْوُوهُ ‏ ‏إِلَى ‏ ‏رِحَالِهِمْ ‏","","",""],[4289,4289,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ حَيْثُ تَوَجَّهَتْ بِهِ ‏","","",""],[4290,4290,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْتَرَ ‏ ‏عَلَى الْبَعِيرِ ‏","","",""],[4291,4291,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي عَلَى حِمَارٍ وَهُوَ مُوَجِّهٌ إِلَى ‏ ‏خَيْبَرَ ‏","","",""],[4292,4292,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏حَمَلَ عَلَى فَرَسٍ فِي سَبِيلِ اللَّهِ فَوَجَدَهَا تُبَاعُ فَسَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ شِرَائِهَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَعُدْ فِي ‏ ‏صَدَقَتِكَ ‏","","",""],[4293,4293,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَأْذَنَتْ أَحَدَكُمْ امْرَأَتُهُ أَنْ تَأْتِيَ الْمَسْجِدَ فَلَا يَمْنَعْهَا ‏ ‏قَالَ ‏ ‏وَكَانَتْ امْرَأَةُ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏تُصَلِّي فِي الْمَسْجِدِ فَقَالَ لَهَا إِنَّكِ لَتَعْلَمِينَ مَا أُحِبُّ فَقَالَتْ وَاللَّهِ لَا أَنْتَهِي حَتَّى ‏ ‏تَنْهَانِي قَالَ فَطُعِنَ ‏ ‏عُمَرُ ‏ ‏وَإِنَّهَا لَفِي الْمَسْجِدِ ‏","","",""],[4294,4294,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ ‏ ‏عُمَرَ ‏ ‏وَهُوَ يَقُولُ وَأَبِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يَنْهَاكُمْ أَنْ تَحْلِفُوا بِآبَائِكُمْ فَإِذَا حَلَفَ أَحَدُكُمْ فَلْيَحْلِفْ بِاللَّهِ أَوْ لِيَصْمُتْ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏فَمَا حَلَفْتُ بِهَا بَعْدُ ذَاكِرًا وَلَا ‏ ‏آثِرًا ‏","","",""],[4295,4295,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْمَرٍ سَعِيدُ بْنُ خُثَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏حَنْظَلَةُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏كَانَ أَبِي ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏إِذَا أَتَى الرَّجُلَ وَهُوَ يُرِيدُ السَّفَرَ قَالَ لَهُ ‏ ‏ادْنُ ‏ ‏حَتَّى أُوَدِّعَكَ كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوَدِّعُنَا فَيَقُولُ ‏ ‏أَسْتَوْدِعُ اللَّهَ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ ‏","","",""],[4296,4296,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ يَعْنِي ابْنَ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ الثَّمَرَةِ حَتَّى ‏ ‏يَبْدُوَ ‏ ‏صَلَاحُهَا نَهَى الْبَائِعَ وَالْمُشْتَرِيَ وَنَهَى أَنْ يُسَافَرَ بِالْقُرْآنِ إِلَى أَرْضِ الْعَدُوِّ مَخَافَةَ أَنْ يَنَالَهُ الْعَدُوُّ ‏","","",""],[4297,4297,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الشِّغَارِ ‏","","",""],[4298,4298,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا لَاعَنَ امْرَأَتَهُ ‏ ‏وَانْتَفَى ‏ ‏مِنْ وَلَدِهَا فَفَرَّقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَهُمَا ‏ ‏فَأَلْحَقَ ‏ ‏الْوَلَدَ بِالْمَرْأَةِ ‏","","",""],[4299,4299,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏وَالْمُزَابَنَةُ اشْتِرَاءُ الثَّمَرِ بِالتَّمْرِ كَيْلًا وَالْكَرْمِ بِالزَّبِيبِ كَيْلًا ‏","","",""],[4300,4300,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجَمَ ‏ ‏يَهُودِيًّا وَيَهُودِيَّةً ‏","","",""],[4301,4301,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْتَرَ ‏ ‏عَلَى الْبَعِيرِ ‏","","",""],[4302,4302,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏تَلَقِّي السِّلَعِ ‏ ‏حَتَّى يُهْبَطَ بِهَا الْأَسْوَاقُ وَنَهَى عَنْ ‏ ‏النَّجْشِ ‏ ‏وَقَالَ لَا يَبِعْ بَعْضُكُمْ عَلَى بَيْعِ بَعْضٍ ‏","","",""],[4303,4303,"","","‏ ‏وَكَانَ إِذَا عَجَّلَ بِهِ السَّيْرُ جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏","","",""],[4304,4304,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطَعَ نَخْلَ ‏ ‏بَنِي النَّضِيرِ ‏ ‏وَحَرَّقَ ‏","","",""],[4305,4305,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏رَكْعَتَيْنِ ‏","","",""],[4306,4306,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الْمُطَّلِبُ بْنُ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ ‏ ‏يَتَوَضَّأُ ثَلَاثًا ثَلَاثًا وَيُسْنِدُ ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4307,4307,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏سَمِعَ صَوْتَ زَمَّارَةِ رَاعٍ فَوَضَعَ أُصْبُعَيْهِ فِي أُذُنَيْهِ وَعَدَلَ ‏ ‏رَاحِلَتَهُ ‏ ‏عَنْ الطَّرِيقِ وَهُوَ يَقُولُ يَا ‏ ‏نَافِعُ ‏ ‏أَتَسْمَعُ فَأَقُولُ نَعَمْ ‏ ‏فَيَمْضِي حَتَّى قُلْتُ لَا فَوَضَعَ يَدَيْهِ وَأَعَادَ ‏ ‏رَاحِلَتَهُ ‏ ‏إِلَى الطَّرِيقِ وَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَمِعَ صَوْتَ زَمَّارَةِ رَاعٍ فَصَنَعَ مِثْلَ هَذَا ‏","","",""],[4308,4308,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏أَنَّ ‏ ‏يَحْيَى بْنَ أَبِي كَثِيرٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا قِلَابَةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَخْرُجُ نَارٌ مِنْ ‏ ‏حَضْرَمَوْتَ ‏ ‏أَوْ ‏ ‏بِحَضْرَمَوْتَ ‏ ‏فَتَسُوقُ النَّاسَ قُلْنَا يَا رَسُولَ اللَّهِ مَا تَأْمُرُنَا قَالَ عَلَيْكُمْ ‏ ‏بِالشَّامِ ‏","","",""],[4309,4309,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ عُبَيْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَكَلَ أَحَدُكُمْ فَلْيَأْكُلْ بِيَمِينِهِ وَإِذَا شَرِبَ فَلْيَشْرَبْ بِيَمِينِهِ فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ وَيَشْرَبُ بِشِمَالِهِ ‏","","",""],[4310,4310,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَلْبَسُ ‏ ‏الْمُحْرِمُ ‏ ‏مِنْ الثِّيَابِ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً مَا يَتْرُكُ ‏ ‏الْمُحْرِمُ ‏ ‏مِنْ الثِّيَابِ ‏ ‏فَقَالَ ‏ ‏لَا يَلْبَسُ الْقَمِيصَ وَلَا ‏ ‏الْبُرْنُسَ ‏ ‏وَلَا السَّرَاوِيلَ وَلَا الْعِمَامَةَ وَلَا ثَوْبًا مَسَّهُ ‏ ‏الْوَرْسُ ‏ ‏وَلَا ‏ ‏الزَّعْفَرَانُ ‏ ‏وَلَا الْخُفَّيْنِ إِلَّا لِمَنْ لَا يَجِدُ نَعْلَيْنِ فَمَنْ لَمْ يَجِدْ النَّعْلَيْنِ فَلْيَلْبَسْ الْخُفَّيْنِ وَلْيَقْطَعْهُمَا حَتَّى يَكُونَا أَسْفَلَ مِنْ الْكَعْبَيْنِ ‏","","",""],[4311,4311,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏يَمْشُونَ أَمَامَ الْجِنَازَةِ ‏","","",""],[4312,4312,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا افْتَتَحَ الصَّلَاةَ رَفَعَ يَدَيْهِ حَتَّى ‏ ‏يُحَاذِيَ ‏ ‏مَنْكِبَيْهِ ‏ ‏وَإِذَا أَرَادَ أَنْ يَرْكَعَ وَبَعْدَمَا يَرْفَعُ رَأْسَهُ مِنْ الرُّكُوعِ ‏ ‏وَقَالَ ‏ ‏سُفْيَانُ ‏ ‏مَرَّةً وَإِذَا رَفَعَ رَأْسَهُ ‏ ‏وَأَكْثَرُ مَا كَانَ يَقُولُ وَبَعْدَمَا يَرْفَعُ رَأْسَهُ مِنْ الرُّكُوعِ وَلَا يَرْفَعُ بَيْنَ السَّجْدَتَيْنِ ‏","","",""],[4313,4313,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الثَّمَرِ بِالتَّمْرِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏كَذَا حَفِظْنَا الثَّمَرِ بِالتَّمْرِ ‏ ‏وَأَخْبَرَهُمْ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي ‏ ‏الْعَرَايَا ‏","","",""],[4314,4314,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْمَعُ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ إِذَا ‏ ‏جَدَّ ‏ ‏بِهِ السَّيْرُ ‏","","",""],[4315,4315,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَمَّا يَقْتُلُ ‏ ‏الْمُحْرِمُ ‏ ‏مِنْ الدَّوَابِّ قَالَ ‏ ‏خَمْسٌ لَا ‏ ‏جُنَاحَ ‏ ‏فِي قَتْلِهِنَّ عَلَى مَنْ قَتَلَهُنَّ فِي ‏ ‏الْحَرَمِ ‏ ‏الْعَقْرَبُ وَالْفَأْرَةُ وَالْغُرَابُ وَالْحِدَأَةُ وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏","","",""],[4316,4316,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الشُّؤْمُ فِي ثَلَاثٍ الْفَرَسِ وَالْمَرْأَةِ وَالدَّارِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏إِنَّمَا نَحْفَظُهُ عَنْ ‏ ‏سَالِمٍ ‏ ‏يَعْنِي الشُّؤْمَ ‏","","",""],[4317,4317,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الَّذِي تَفُوتُهُ صَلَاةُ الْعَصْرِ فَكَأَنَّمَا وُتِرَ أَهْلَهُ وَمَالَهُ ‏","","",""],[4318,4318,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏رِوَايَةً وَقَالَ مَرَّةً ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَتْرُكُوا النَّارَ فِي بُيُوتِكُمْ حِينَ تَنَامُونَ ‏","","",""],[4319,4319,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏رَأَى رَجُلٌ أَنَّ لَيْلَةَ الْقَدْرِ لَيْلَةُ سَبْعٍ وَعِشْرِينَ أَوْ كَذَا وَكَذَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَى رُؤْيَاكُمْ قَدْ ‏ ‏تَوَاطَأَتْ ‏ ‏فَالْتَمِسُوهَا فِي الْعَشْرِ الْبَوَاقِي فِي ‏ ‏الْوِتْرِ ‏ ‏مِنْهَا ‏","","",""],[4320,4320,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏سَمِعَ ‏ ‏سَالِمًا ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ يَقُولُ وَأَبِي وَأَبِي فَقَالَ إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏يَنْهَاكُمْ أَنْ تَحْلِفُوا بِآبَائِكُمْ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏فَوَاللَّهِ فَوَاللَّهِ مَا حَلَفْتُ بِهَا ذَاكِرًا وَلَا ‏ ‏آثِرًا ‏","","",""],[4321,4321,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏اقْتَنَى ‏ ‏كَلْبًا إِلَّا كَلْبَ صَيْدٍ أَوْ مَاشِيَةٍ نَقَصَ مِنْ أَجْرِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطَانِ ‏","","",""],[4322,4322,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا حَسَدَ إِلَّا فِي اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ الْقُرْآنَ فَهُوَ يَقُومُ بِهِ ‏ ‏آنَاءَ ‏ ‏اللَّيْلِ وَالنَّهَارِ وَرَجُلٌ آتَاهُ اللَّهُ مَالًا فَهُوَ يُنْفِقُهُ فِي الْحَقِّ ‏ ‏آنَاءَ ‏ ‏اللَّيْلِ وَالنَّهَارِ ‏","","",""],[4323,4323,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏بِلَالًا ‏ ‏يُؤَذِّنُ بِلَيْلٍ فَكُلُوا وَاشْرَبُوا حَتَّى يُؤَذِّنَ ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏","","",""],[4324,4324,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ بَاعَ عَبْدًا وَلَهُ مَالٌ فَمَالُهُ لِلْبَائِعِ إِلَّا أَنْ يَشْتَرِطَ ‏ ‏الْمُبْتَاعُ ‏ ‏وَمَنْ بَاعَ نَخْلًا ‏ ‏مُؤَبَّرًا ‏ ‏فَالثَّمَرَةُ لِلْبَائِعِ إِلَّا أَنْ يَشْتَرِطَ ‏ ‏الْمُبْتَاعُ ‏","","",""],[4325,4325,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ جَاءَ مِنْكُمْ الْجُمُعَةَ فَلْيَغْتَسِلْ ‏","","",""],[4326,4326,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا يَعِظُ أَخَاهُ فِي الْحَيَاءِ فَقَالَ الْحَيَاءُ مِنْ الْإِيمَانِ ‏","","",""],[4327,4327,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَّتَ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏مُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏وَأَهْلِ ‏ ‏الشَّامِ ‏ ‏مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏وَأَهْلِ ‏ ‏نَجْدٍ ‏ ‏مِنْ ‏ ‏قَرْنٍ ‏ ‏قَالَ ‏ ‏وَذُكِرَ لِي وَلَمْ أَسْمَعْهُ ‏ ‏وَيُهِلُّ ‏ ‏أَهْلُ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏","","",""],[4328,4328,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَأْذَنَتْ أَحَدَكُمْ امْرَأَتُهُ إِلَى الْمَسْجِدِ فَلَا يَمْنَعْهَا ‏","","",""],[4329,4329,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوا الْحَيَّاتِ وَذَا ‏ ‏الطُّفْيَتَيْنِ ‏ ‏وَالْأَبْتَرَ ‏ ‏فَإِنَّهُمَا ‏ ‏يَلْتَمِسَانِ ‏ ‏الْبَصَرَ وَيَسْتَسْقِطَانِ ‏ ‏الْحَبَلَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَقْتُلُ كُلَّ حَيَّةٍ وَجَدَهَا فَرَآهُ ‏ ‏أَبُو لُبَابَةَ ‏ ‏أَوْ ‏ ‏زَيْدُ بْنُ الْخَطَّابِ ‏ ‏وَهُوَ يُطَارِدُ حَيَّةً فَقَالَ إِنَّهُ قَدْ ‏ ‏نُهِيَ عَنْ ذَوَاتِ الْبُيُوتِ ‏","","",""],[4330,4330,"","","‏ ‏قَالَ ‏ ‏قَرَأَ عَلَيَّ ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَأْكُلْ أَحَدُكُمْ مِنْ لَحْمِ أُضْحِيَّتِهِ فَوْقَ ثَلَاثٍ ‏","","",""],[4331,4331,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ كَيْفَ يُصَلَّى بِاللَّيْلِ قَالَ ‏ ‏لِيُصَلِّ أَحَدُكُمْ مَثْنَى مَثْنَى فَإِذَا خَشِيَ الصُّبْحَ ‏ ‏فَلْيُوتِرْ ‏ ‏بِوَاحِدَةٍ ‏","","",""],[4332,4332,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ ‏ ‏الْوَلَاءِ ‏ ‏وَعَنْ هِبَتِهِ ‏","","",""],[4333,4333,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَدْخُلُوا عَلَى هَؤُلَاءِ الْقَوْمِ الَّذِينَ عُذِّبُوا إِلَّا أَنْ تَكُونُوا بَاكِينَ فَإِنْ لَمْ تَكُونُوا بَاكِينَ فَلَا تَدْخُلُوا عَلَيْهِمْ فَإِنِّي أَخَافُ أَنْ يُصِيبَكُمْ مِثْلُ مَا أَصَابَهُمْ ‏","","",""],[4334,4334,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏سُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الضَّبِّ فَقَالَ ‏ ‏لَا آكُلُهُ وَلَا أُحَرِّمُهُ ‏","","",""],[4335,4335,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏سَمِعْتُهُ مِنِ ‏ ‏ابْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَلَّمَ عَلَيْكَ الْيَهُودِيُّ فَإِنَّمَا يَقُولُ ‏ ‏السَّامُ ‏ ‏عَلَيْكَ فَقُلْ وَعَلَيْكَ ‏ ‏وَقَالَ مَرَّةً إِذَا سَلَّمَ عَلَيْكُمْ ‏ ‏الْيَهُودُ ‏ ‏فَقُولُوا وَعَلَيْكُمْ فَإِنَّهُمْ يَقُولُونَ ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ ‏","","",""],[4336,4336,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كُنْتُمْ ثَلَاثَةً فَلَا ‏ ‏يَتَنَاجَ ‏ ‏اثْنَانِ دُونَ الثَّالِثِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏يَتَنَاجَى ‏ ‏الرَّجُلَانِ دُونَ الثَّالِثِ إِذَا كَانُوا ثَلَاثَةً ‏","","",""],[4337,4337,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَايِعُ ‏ ‏عَلَى السَّمْعِ وَالطَّاعَةِ ثُمَّ يَقُولُ فِيمَا اسْتَطَعْتَ ‏ ‏وَقَالَ ‏ ‏مَرَّةً فَيُلَقِّنُ أَحَدَنَا فِيمَا اسْتَطَعْتَ ‏","","",""],[4338,4338,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا أَوْ يَكُونَ بَيْعَ ‏ ‏خِيَارٍ ‏","","",""],[4339,4339,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏ابْنَ ابْنِهِ ‏ ‏عَبْدَ اللَّهِ بْنَ وَاقِدٍ ‏ ‏يَا بُنَيَّ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَنْظُرُ اللَّهُ عَزَّ وَجَلَّ إِلَى مَنْ جَرَّ ‏ ‏إِزَارَهُ ‏ ‏خُيَلَاءَ ‏","","",""],[4340,4340,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏دَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسْجِدَ ‏ ‏بَنِي عَمْرِو بْنِ عَوْفٍ ‏ ‏مَسْجِدَ قُبَاءَ ‏ ‏يُصَلِّي فِيهِ فَدَخَلَتْ عَلَيْهِ رِجَالُ ‏ ‏الْأَنْصَارِ ‏ ‏يُسَلِّمُونَ عَلَيْهِ وَدَخَلَ مَعَهُ ‏ ‏صُهَيْبٌ ‏ ‏فَسَأَلْتُ ‏ ‏صُهَيْبًا ‏ ‏كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصْنَعُ إِذَا سُلِّمَ عَلَيْهِ قَالَ يُشِيرُ بِيَدِهِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏قُلْتُ لِرَجُلٍ سَلْ ‏ ‏زَيْدًا ‏ ‏أَسَمِعْتَهُ مِنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَهِبْتُ أَنَا أَنْ أَسْأَلَهُ فَقَالَ يَا ‏ ‏أَبَا أُسَامَةَ ‏ ‏سَمِعْتَهُ مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ أَمَّا أَنَا فَقَدْ رَأَيْتُهُ فَكَلَّمْتُهُ ‏","","",""],[4341,4341,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَفَلَ مِنْ حَجٍّ أَوْ عُمْرَةٍ أَوْ غَزْوٍ فَأَوْفَى عَلَى ‏ ‏فَدْفَدٍ ‏ ‏مِنْ الْأَرْضِ قَالَ ‏ ‏لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ صَدَقَ اللَّهُ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ ‏ ‏آيِبُونَ ‏ ‏إِنْ شَاءَ اللَّهُ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ ‏","","",""],[4342,4342,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَقُولُ هَذِهِ ‏ ‏الْبَيْدَاءُ ‏ ‏الَّتِي يَكْذِبُونَ فِيهَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ ‏ ‏مَا أَحْرَمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا مِنْ عِنْدِ ‏ ‏الْمَسْجِدِ ‏","","",""],[4343,4343,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَبِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ صَلَاةِ اللَّيْلِ فَقَالَ مَثْنَى مَثْنَى فَإِذَا خِفْتَ الصُّبْحَ فَأَوْتِرْ بِوَاحِدَةٍ ‏","","",""],[4344,4344,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَبِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَغْلِبَنَّكُمْ ‏ ‏الْأَعْرَابُ ‏ ‏عَلَى اسْمِ صَلَاتِكُمْ أَلَا وَإِنَّهَا الْعِشَاءُ وَإِنَّهُمْ يُعْتِمُونَ بِالْإِبِلِ ‏ ‏أَوْ عَنْ الْإِبِلِ ‏","","",""],[4345,4345,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏وَهِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ الضَّبِّ فَقَالَ ‏ ‏لَا آكُلُهُ وَلَا أُحَرِّمُهُ ‏","","",""],[4346,4346,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ فَلَمَّا رَأَيْتُهُ أَسْرَعْتُ فَدَخَلْتُ الْمَسْجِدَ فَجَلَسْتُ فَلَمْ أَسْمَعْ حَتَّى نَزَلَ فَسَأَلْتُ ‏ ‏النَّاسَ ‏ ‏أَيَّ شَيْءٍ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا ‏ ‏نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏أَنْ ‏ ‏يُنْتَبَذَ ‏ ‏فِيهِ ‏","","",""],[4347,4347,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏مُسْلِمُ بْنُ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ الرَّحْمَنِ الْمُعَاوِيِّ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ إِلَى جَنْبِ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقَلَّبْتُ الْحَصَى فَقَالَ ‏ ‏لَا تُقَلِّبْ الْحَصَى فَإِنَّهُ مِنْ الشَّيْطَانِ وَلَكِنْ كَمَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْعَلُ كَانَ يُحَرِّكُهُ هَكَذَا ‏ ‏قَالَ ‏ ‏أَبُو عَبْد اللَّهِ ‏ ‏يَعْنِي مَسْحَةً ‏","","",""],[4348,4348,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُسَافِرُوا بِالْقُرْآنِ فَإِنِّي أَخَافُ أَنْ يَنَالَهُ الْعَدُوُّ ‏","","",""],[4349,4349,"","","‏ ‏سَمِعْت ‏ ‏سُفْيَانَ ‏ ‏قَالَ ‏ ‏إِنَّهُ نَذَرَ ‏ ‏يَعْنِي أَنْ يَعْتَكِفَ فِي ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ ‏فَسَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُ ‏ ‏قِيلَ ‏ ‏لِسُفْيَانَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ ‏ ‏عُمَرَ ‏ ‏نَذَرَ قَالَ نَعَمْ ‏","","",""],[4350,4350,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ قَالَ ‏ ‏حَقٌّ عَلَى كُلِّ مُسْلِمٍ أَنْ يَبِيتَ لَيْلَتَيْنِ وَلَهُ مَا ‏ ‏يُوصِي فِيهِ إِلَّا وَوَصِيَّتُهُ مَكْتُوبَةٌ عِنْدَهُ ‏","","",""],[4351,4351,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏سَرِيَّةً ‏ ‏إِلَى ‏ ‏نَجْدٍ ‏ ‏فَبَلَغَتْ سِهَامُهُمْ اثْنَيْ عَشَرَ بَعِيرًا ‏ ‏وَنَفَّلَنَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعِيرًا بَعِيرًا ‏","","",""],[4352,4352,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏بِضَجْنَانَ ‏ ‏فَأَقَامَ الصَّلَاةَ ثُمَّ نَادَى أَلَا صَلُّوا فِي ‏ ‏الرِّحَالِ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ مُنَادِيًا فِي اللَّيْلَةِ الْمَطِيرَةِ ‏ ‏أَوْ الْبَارِدَةِ ‏ ‏أَلَا صَلُّوا فِي ‏ ‏الرِّحَالِ ‏","","",""],[4353,4353,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ فَقَالَ إِنْ شَاءَ اللَّهُ فَقَدْ ‏ ‏اسْتَثْنَى ‏","","",""],[4354,4354,"","","‏ ‏قَالَ ‏ ‏قَرَأَ عَلَيَّ ‏ ‏سُفْيَانُ ‏ ‏سَمِعْتُ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ حَبَلِ الْحَبَلَةِ ‏","","",""],[4355,4355,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ جُدْعَانَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ رَبِيعَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏وَهُوَ عَلَى دَرَجِ ‏ ‏الْكَعْبَةِ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي صَدَقَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ أَلَا إِنَّ قَتِيلَ الْعَمْدِ الْخَطَإِ بِالسَّوْطِ أَوْ الْعَصَا فِيهِ مِائَةٌ مِنْ الْإِبِلِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً الْمُغَلَّظَةُ فِيهَا أَرْبَعُونَ ‏ ‏خَلِفَةً ‏ ‏فِي بُطُونِهَا أَوْلَادُهَا إِنَّ كُلَّ ‏ ‏مَأْثُرَةٍ ‏ ‏كَانَتْ فِي الْجَاهِلِيَّةِ وَدَمٍ وَدَعْوَى ‏ ‏وَقَالَ ‏ ‏مَرَّةً وَدَمٍ وَمَالٍ ‏ ‏تَحْتَ قَدَمَيَّ هَاتَيْنِ إِلَّا مَا كَانَ مِنْ ‏ ‏سِقَايَةِ ‏ ‏الْحَاجِّ ‏ ‏وَسِدَانَةِ ‏ ‏الْبَيْتِ ‏ ‏فَإِنِّي ‏ ‏أُمْضِيهِمَا لِأَهْلِهِمَا عَلَى مَا كَانَتْ ‏","","",""],[4356,4356,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏سَمِعَ ‏ ‏صَدَقَةَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَقُولُ ‏ ‏يَعْنِي ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُهِلُّ ‏ ‏أَهْلُ ‏ ‏نَجْدٍ ‏ ‏مِنْ ‏ ‏قَرْنٍ ‏ ‏وَأَهْلُ ‏ ‏الشَّامِ ‏ ‏مِنْ ‏ ‏الْجُحْفَةِ ‏ ‏وَأَهْلُ ‏ ‏الْيَمَنِ ‏ ‏مِنْ ‏ ‏يَلَمْلَمَ ‏ ‏وَلَمْ يَسْمَعْهُ ‏ ‏ابْنُ عُمَرَ ‏ ‏وَسَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُهَلُّ ‏ ‏أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏مِنْ ‏ ‏ذِي الْحُلَيْفَةِ ‏ ‏قَالُوا لَهُ فَأَيْنَ أَهْلُ ‏ ‏الْعِرَاقِ ‏ ‏قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏لَمْ يَكُنْ يَوْمَئِذٍ ‏","","",""],[4357,4357,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏اسْتِلَامَ ‏ ‏الرُّكْنَيْنِ ‏ ‏يَحُطَّانِ ‏ ‏الذُّنُوبَ ‏","","",""],[4358,4358,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعَ ‏ ‏عَمْرٌو ‏ ‏ابْنَ عُمَرَ ‏ ‏كُنَّا ‏ ‏نُخَابِرُ ‏ ‏وَلَا نَرَى بِذَلِكَ ‏ ‏بَأْسًا ‏ ‏حَتَّى زَعَمَ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهُ فَتَرَكْنَاهُ ‏","","",""],[4359,4359,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعَ ‏ ‏عَمْرٌو ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْمُتَلَاعِنَيْنِ ‏ ‏حِسَابُكُمَا عَلَى اللَّهِ أَحَدُكُمَا كَاذِبٌ لَا سَبِيلَ لَكَ عَلَيْهَا قَالَ يَا رَسُولَ اللَّهِ مَالِي قَالَ لَا مَالَ لَكَ إِنْ كُنْتَ صَدَقْتَ عَلَيْهَا فَهُوَ بِمَا اسْتَحْلَلْتَ مِنْ فَرْجِهَا وَإِنْ كُنْتَ كَذَبْتَ عَلَيْهَا فَذَاكَ أَبْعَدُ لَكَ ‏","","",""],[4360,4360,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرٌو ‏ ‏عَنْ ‏ ‏أَبِي الْعَبَّاسِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قِيلَ ‏ ‏لِسُفْيَانَ ‏ ‏ابْنُ عَمْرٍو ‏ ‏قَالَ لَا ‏ ‏ابْنُ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا حَاصَرَ أَهْلَ ‏ ‏الطَّائِفِ ‏ ‏وَلَمْ يَقْدِرْ مِنْهُمْ عَلَى شَيْءٍ قَالَ ‏ ‏إِنَّا ‏ ‏قَافِلُونَ ‏ ‏غَدًا إِنْ شَاءَ اللَّهُ فَكَأَنَّ الْمُسْلِمِينَ كَرِهُوا ذَلِكَ فَقَالَ ‏ ‏اغْدُوا ‏ ‏فَغَدَوْا ‏ ‏عَلَى الْقِتَالِ فَأَصَابَهُمْ جِرَاحٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا ‏ ‏قَافِلُونَ ‏ ‏غَدًا إِنْ شَاءَ اللَّهُ فَسُرَّ الْمُسْلِمُونَ فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4361,4361,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ الْعَبْدُ بَيْنَ اثْنَيْنِ فَأَعْتَقَ أَحَدُهُمَا نَصِيبَهُ فَإِنْ كَانَ مُوسِرًا قُوِّمَ عَلَيْهِ قِيمَةً لَا ‏ ‏وَكْسَ ‏ ‏وَلَا ‏ ‏شَطَطَ ‏ ‏ثُمَّ يُعْتَقُ ‏","","",""],[4362,4362,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ الشَّيْبَانِيِّ ‏ ‏بِعْتُ مَا فِي رُءُوسِ نَخْلِي بِمِائَةِ ‏ ‏وَسْقٍ ‏ ‏إِنْ زَادَ فَلَهُمْ وَإِنْ نَقَصَ فَلَهُمْ فَسَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏فَقَالَ ‏ ‏نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَرَخَّصَ فِي ‏ ‏الْعَرَايَا ‏","","",""],[4363,4363,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏بَيْنَهُمَا ‏ ‏سَالِمٌ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي بَعْدَ الْجُمُعَةِ رَكْعَتَيْنِ ‏","","",""],[4364,4364,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَضَاءَ الْفَجْرُ صَلَّى رَكْعَتَيْنِ ‏","","",""],[4365,4365,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَدْرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عُمَرَ ‏ ‏وَهُوَ فِي بَعْضِ أَسْفَارِهِ وَهُوَ يَقُولُ وَأَبِي وَأَبِي فَقَالَ ‏ ‏إِنَّ اللَّهَ يَنْهَاكُمْ أَنْ تَحْلِفُوا بِآبَائِكُمْ فَمَنْ كَانَ حَالِفًا فَلْيَحْلِفْ بِاللَّهِ وَإِلَّا فَلْيَصْمُتْ ‏","","",""],[4366,4366,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَبَّقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَيْلَ فَأَرْسَلَ مَا ‏ ‏ضُمِّرَ ‏ ‏مِنْهَا مِنْ ‏ ‏الْحَفْيَاءِ ‏ ‏وَأَرْسَلَ مَا لَمْ ‏ ‏يُضَمَّرْ ‏ ‏مِنْهَا مِنْ ‏ ‏ثَنِيَّةِ الْوَدَاعِ ‏ ‏إِلَى مَسْجِدِ ‏ ‏بَنِي زُرَيْقٍ ‏","","",""],[4367,4367,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ مُوسَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏خَرَجَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يُرِيدُ الْعُمْرَةَ فَأَخْبَرُوهُ أَنَّ ‏ ‏بِمَكَّةَ ‏ ‏أَمْرًا فَقَالَ ‏ ‏أُهِلُّ بِالْعُمْرَةِ فَإِنْ حُبِسْتُ ‏ ‏صَنَعْتُ كَمَا صَنَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَهَلَّ بِالْعُمْرَةِ فَلَمَّا سَارَ قَلِيلًا وَهُوَ ‏ ‏بِالْبَيْدَاءِ ‏ ‏قَالَ مَا سَبِيلُ الْعُمْرَةِ إِلَّا سَبِيلُ الْحَجِّ أُوجِبُ حَجًّا وَقَالَ أُشْهِدُكُمْ أَنِّي قَدْ أَوْجَبْتُ حَجًّا فَإِنَّ سَبِيلَ الْحَجِّ سَبِيلُ الْعُمْرَةِ فَقَدِمَ ‏ ‏مَكَّةَ ‏ ‏فَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏سَبْعًا وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏سَبْعًا وَقَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ أَتَى ‏ ‏قُدَيْدًا ‏ ‏فَاشْتَرَى هَدْيًا فَسَاقَهُ مَعَهُ ‏","","",""],[4368,4368,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَتَى ‏ ‏قُدَيْدًا ‏ ‏وَاشْتَرَى هَدْيَهُ فَطَافَ ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَقَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَنَعَ هَكَذَا ‏","","",""],[4369,4369,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ يَعْنِي ابْنَ مُوسَى ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏سَمِعْتُ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏بَنِي سَلِمَةَ ‏ ‏يُحَدِّثُ ‏ ‏ابْنَ عُمَرَ ‏ ‏أَنَّ جَارِيَةً ‏ ‏لِكَعْبِ بْنِ مَالِكٍ ‏ ‏كَانَتْ ‏ ‏تَرْعَى غَنَمًا لَهُ ‏ ‏بِسَلْعٍ ‏ ‏بَلَغَ الْمَوْتُ شَاةً مِنْهَا فَأَخَذَتْ ‏ ‏ظُرَرَةً ‏ ‏فَذَكَّتْهَا ‏ ‏بِهِ فَأَمَرَهُ بِأَكْلِهَا ‏","","",""],[4370,4370,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ذُؤَيْبٍ ‏ ‏مِنْ ‏ ‏بَنِي أَسَدِ بْنِ عَبْدِ الْعُزَّى ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ ‏ ‏ابْنِ عُمَرَ ‏ ‏إِلَى الْحِمَى فَلَمَّا غَرُبَتْ الشَّمْسُ هِبْنَا أَنْ نَقُولَ لَهُ الصَّلَاةَ حَتَّى ذَهَبَ بَيَاضُ ‏ ‏الْأُفُقِ ‏ ‏وَذَهَبَتْ ‏ ‏فَحْمَةُ ‏ ‏الْعِشَاءِ ‏ ‏نَزَلَ فَصَلَّى بِنَا ثَلَاثًا وَاثْنَتَيْنِ وَالْتَفَتَ إِلَيْنَا وَقَالَ هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَ ‏","","",""],[4371,4371,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏صَحِبْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَلَمْ أَسْمَعْهُ يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا حَدِيثًا كُنَّا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُتِيَ ‏ ‏بِجُمَّارَةٍ ‏ ‏فَقَالَ ‏ ‏إِنَّ مِنْ الشَّجَرِ شَجَرَةً مَثَلُهَا كَمَثَلِ الرَّجُلِ الْمُسْلِمِ ‏ ‏فَأَرَدْتُ أَنْ أَقُولَ هِيَ النَّخْلَةُ فَنَظَرْتُ فَإِذَا أَنَا أَصْغَرُ الْقَوْمِ فَسَكَتُّ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هِيَ النَّخْلَةُ ‏","","",""],[4372,4372,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏شَهِدَ ‏ ‏ابْنُ عُمَرَ ‏ ‏الْفَتْحَ وَهُوَ ابْنُ عِشْرِينَ سَنَةً وَمَعَهُ فَرَسٌ ‏ ‏حَرُونٌ ‏ ‏وَرُمْحٌ ثَقِيلٌ فَذَهَبَ ‏ ‏ابْنُ عُمَرَ ‏ ‏يَخْتَلِي لِفَرَسِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏إِنَّ ‏ ‏عَبْدَ اللَّهِ ‏","","",""],[4373,4373,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏أَخْبَرَنَا ‏ ‏عِمْرَانُ يَعْنِي ابْنَ حُدَيْرٍ ‏ ‏وَوَكِيعٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عُطَارِدٍ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏السَّدُوسِيِّ أَبِي الْبَزَرِيِّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الشُّرْبِ قَائِمًا فَقَالَ قَدْ ‏ ‏كُنَّا عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَشْرَبُ قِيَامًا وَنَأْكُلُ وَنَحْنُ ‏ ‏نَسْعَى ‏","","",""],[4374,4374,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏كَانُوا يَبْدَءُونَ بِالصَّلَاةِ قَبْلَ الْخُطْبَةِ فِي الْعِيدِ ‏","","",""],[4375,4375,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَاعَنَ ‏ ‏بَيْنَ رَجُلٍ وَامْرَأَتِهِ وَفَرَّقَ بَيْنَهُمَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنْ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[4376,4376,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَعْفَرِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسْأَلُ عَنْ الْمَاءِ يَكُونُ بِأَرْضِ ‏ ‏الْفَلَاةِ ‏ ‏وَمَا ‏ ‏يَنُوبُهُ ‏ ‏مِنْ الدَّوَابِّ وَالسِّبَاعِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا كَانَ الْمَاءُ قَدْرَ الْقُلَّتَيْنِ لَمْ يَحْمِلْ ‏ ‏الْخَبَثَ ‏","","",""],[4377,4377,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏وَاسِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَقِيتُ ‏ ‏يَوْمًا فَوْقَ بَيْتِ ‏ ‏حَفْصَةَ ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى حَاجَتِهِ مُسْتَقْبِلَ ‏ ‏الشَّامِ ‏ ‏مُسْتَدْبِرَ الْقِبْلَةِ ‏","","",""],[4378,4378,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ إِدْرِيسَ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا فِي زَمَنِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَنَامُ فِي الْمَسْجِدِ نَقِيلُ فِيهِ وَنَحْنُ شَبَابٌ ‏","","",""],[4379,4379,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَصَابَ ‏ ‏عُمَرُ ‏ ‏أَرْضًا ‏ ‏بِخَيْبَرَ ‏ ‏فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَأْمَرَهُ ‏ ‏فِيهَا فَقَالَ ‏ ‏أَصَبْتُ ‏ ‏أَرْضًا ‏ ‏بِخَيْبَرَ ‏ ‏لَمْ ‏ ‏أُصِبْ ‏ ‏مَالًا قَطُّ ‏ ‏أَنْفَسَ ‏ ‏عِنْدِي مِنْهُ فَمَا تَأْمُرُ بِهِ قَالَ ‏ ‏إِنْ شِئْتَ ‏ ‏حَبَسْتَ ‏ ‏أَصْلَهَا ‏ ‏وَتَصَدَّقْتَ ‏ ‏بِهَا ‏ ‏قَالَ ‏ ‏فَتَصَدَّقَ بِهَا ‏ ‏عُمَرُ ‏ ‏أَنْ لَا تُبَاعَ وَلَا تُوهَبَ وَلَا تُوَرَّثَ قَالَ فَتَصَدَّقَ بِهَا ‏ ‏عُمَرُ ‏ ‏فِي الْفُقَرَاءِ وَالْقُرْبَى وَالرِّقَابِ وَفِي سَبِيلِ اللَّهِ تَبَارَكَ وَتَعَالَى وَابْنِ السَّبِيلِ وَالضَّيْفِ لَا ‏ ‏جُنَاحَ ‏ ‏عَلَى مَنْ ‏ ‏وَلِيَهَا ‏ ‏أَنْ يَأْكُلَ مِنْهَا بِالْمَعْرُوفِ أَوْ يُطْعِمَ صَدِيقًا غَيْرَ ‏ ‏مُتَأَثِّلٍ ‏ ‏فِيهِ ‏","","",""],[4380,4380,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏غَيْلَانَ بْنَ سَلَمَةَ الثَّقَفِيَّ ‏ ‏أَسْلَمَ وَتَحْتَهُ عَشْرُ نِسْوَةٍ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اخْتَرْ مِنْهُنَّ أَرْبَعًا ‏","","",""],[4381,4381,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏قَالَ ‏ ‏رُبَّمَا أَمَّنَا ‏ ‏ابْنُ عُمَرَ ‏ ‏بِالسُّورَتَيْنِ وَالثَّلَاثِ فِي ‏ ‏الْفَرِيضَةِ ‏","","",""],[4382,4382,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ تِسْعٌ وَعِشْرُونَ هَكَذَا وَهَكَذَا فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَاقْدُرُوا لَهُ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِذَا كَانَ لَيْلَةُ تِسْعٍ وَعِشْرِينَ وَكَانَ فِي السَّمَاءِ سَحَابٌ أَوْ ‏ ‏قَتَرٌ ‏ ‏أَصْبَحَ صَائِمًا ‏","","",""],[4383,4383,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تَتَحَرَّوْا ‏ ‏بِصَلَاتِكُمْ طُلُوعَ الشَّمْسِ وَلَا غُرُوبَهَا فَإِنَّهَا تَطْلُعُ بَيْنَ ‏ ‏قَرْنَيْ شَيْطَانٍ ‏ ‏فَإِذَا طَلَعَ حَاجِبُ الشَّمْسِ فَلَا تُصَلُّوا حَتَّى تَبْرُزَ وَإِذَا غَابَ حَاجِبُ الشَّمْسِ فَلَا تُصَلُّوا حَتَّى تَغِيبَ ‏","","",""],[4384,4384,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏يَوْمَ يَقُومُ النَّاسُ لِرَبِّ الْعَالَمِينَ ‏} ‏يَقُومُ فِي ‏ ‏رَشْحِهِ ‏ ‏إِلَى أَنْصَافِ أُذُنَيْهِ ‏","","",""],[4385,4385,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْكُزُ ‏ ‏الْحَرْبَةَ ‏ ‏يُصَلِّي إِلَيْهَا ‏","","",""],[4386,4386,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُسَافِرْ الْمَرْأَةُ ثَلَاثًا إِلَّا وَمَعَهَا ذُو ‏ ‏مَحْرَمٍ ‏","","",""],[4387,4387,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْخَيْلُ ‏ ‏بِنَوَاصِيهَا ‏ ‏الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[4388,4388,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏رَقِيتُ ‏ ‏يَوْمًا عَلَى بَيْتِ ‏ ‏حَفْصَةَ ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى حَاجَتِهِ مُسْتَدْبِرَ ‏ ‏الْبَيْتِ ‏ ‏مُسْتَقْبِلَ ‏ ‏الشَّامِ ‏","","",""],[4389,4389,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏أَخْبَرَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يَرْمُلُ ثَلَاثًا وَيَمْشِي أَرْبَعًا وَيَزْعُمُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ وَكَانَ يَمْشِي مَا بَيْنَ الرُّكْنَيْنِ قَالَ إِنَّمَا كَانَ يَمْشِي مَا بَيْنَهُمَا لِيَكُونَ أَيْسَرَ لِاسْتِلَامِهِ ‏","","",""],[4390,4390,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الضَّبِّ وَهُوَ عَلَى الْمِنْبَرِ فَقَالَ ‏ ‏لَا آكُلُهُ وَلَا أَنَهَى عَنْهُ ‏","","",""],[4391,4391,"","","‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَكَلَ مِنْ هَذِهِ الشَّجَرَةِ فَلَا يَأْتِيَنَّ الْمَسْجِدَ ‏","","",""],[4392,4392,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُصَلِّي عَلَى رَاحِلَتِهِ وَيُوتِرُ عَلَيْهَا وَيَذْكُرُ ذَلِكَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[4393,4393,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي تَفُوتُهُ صَلَاةُ الْعَصْرِ مُتَعَمِّدًا حَتَّى تَغْرُبَ الشَّمْسُ فَكَأَنَّمَا ‏ ‏وُتِرَ ‏ ‏أَهْلَهُ وَمَالَهُ ‏","","",""],[4394,4394,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏الْمِنْهَالِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏أَنَّهُ مَرَّ عَلَى قَوْمٍ وَقَدْ نَصَبُوا دَجَاجَةً حَيَّةً يَرْمُونَهَا فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَنَ مَنْ ‏ ‏مَثَّلَ ‏ ‏بِالْبَهَائِمِ ‏","","",""],[4395,4395,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبْجَرَ ‏ ‏عَنْ ‏ ‏ثُوَيْرِ بْنِ أَبِي فَاخِتَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏أَدْنَى ‏ ‏أَهْلِ الْجَنَّةِ مَنْزِلَةً لَيَنْظُرُ فِي مُلْكِ أَلْفَيْ سَنَةٍ يَرَى أَقْصَاهُ كَمَا يَرَى أَدْنَاهُ يَنْظُرُ فِي أَزْوَاجِهِ وَخَدَمِهِ وَإِنَّ أَفْضَلَهُمْ مَنْزِلَةً لَيَنْظُرُ فِي وَجْهِ اللَّهِ تَعَالَى كُلَّ يَوْمٍ مَرَّتَيْنِ ‏","","",""],[4396,4396,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سُوقَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَفْصٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ أَذْنَبْتُ ذَنْبًا كَبِيرًا فَهَلْ لِي تَوْبَةٌ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَكَ وَالِدَانِ قَالَ لَا قَالَ فَلَكَ خَالَةٌ قَالَ نَعَمْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبِرَّهَا إِذًا ‏","","",""],[4397,4397,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ ‏ ‏مَكَّةَ ‏ ‏دَخَلَ مِنْ ‏ ‏الثَّنِيَّةِ الْعُلْيَا ‏ ‏وَإِذَا خَرَجَ خَرَجَ مِنْ ‏ ‏الثَّنِيَّةِ السُّفْلَى ‏","","",""],[4398,4398,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏كُنَّا نَعُدُّ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَيٌّ وَأَصْحَابُهُ ‏ ‏مُتَوَافِرُونَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَعُمَرُ ‏ ‏وَعُثْمَانُ ‏ ‏ثُمَّ نَسْكُتُ ‏","","",""],[4399,4399,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَوْنِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏بَيْنَا نَحْنُ نُصَلِّي مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ قَالَ رَجُلٌ فِي الْقَوْمِ ‏ ‏اللَّهُ أَكْبَرُ كَبِيرًا وَالْحَمْدُ لِلَّهِ كَثِيرًا وَسُبْحَانَ اللَّهِ بُكْرَةً وَأَصِيلًا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ الْقَائِلُ كَذَا وَكَذَا فَقَالَ رَجُلٌ مِنْ الْقَوْمِ أَنَا يَا رَسُولَ اللَّهِ قَالَ عَجِبْتُ لَهَا فُتِحَتْ لَهَا أَبْوَابُ السَّمَاءِ ‏ ‏قَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏فَمَا تَرَكْتُهُنَّ مُنْذُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ذَلِكَ ‏","","",""],[4400,4400,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ عُمَرَ ‏ ‏إِذَا دَخَلَ ‏ ‏أَدْنَى ‏ ‏الْحَرَمِ ‏ ‏أَمْسَكَ عَنْ التَّلْبِيَةِ فَإِذَا انْتَهَى إِلَى ‏ ‏ذِي طُوًى ‏ ‏بَاتَ فِيهِ حَتَّى يُصْبِحَ ثُمَّ يُصَلِّيَ ‏ ‏الْغَدَاةَ ‏ ‏وَيَغْتَسِلَ وَيُحَدِّثَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ثُمَّ يَدْخُلُ ‏ ‏مَكَّةَ ‏ ‏ضُحًى فَيَأْتِي ‏ ‏الْبَيْتَ ‏ ‏فَيَسْتَلِمُ ‏ ‏الْحَجَرَ وَيَقُولُ بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ ثُمَّ ‏ ‏يَرْمُلُ ‏ ‏ثَلَاثَةَ أَطْوَافٍ يَمْشِي مَا بَيْنَ الرُّكْنَيْنِ فَإِذَا أَتَى عَلَى الْحَجَرِ ‏ ‏اسْتَلَمَهُ ‏ ‏وَكَبَّرَ أَرْبَعَةَ أَطْوَافٍ مَشْيًا ثُمَّ يَأْتِي ‏ ‏الْمَقَامَ ‏ ‏فَيُصَلِّي رَكْعَتَيْنِ ثُمَّ يَرْجِعُ إِلَى الْحَجَرِ ‏ ‏فَيَسْتَلِمُهُ ‏ ‏ثُمَّ يَخْرُجُ إِلَى ‏ ‏الصَّفَا ‏ ‏مِنْ الْبَابِ الْأَعْظَمِ فَيَقُومُ عَلَيْهِ فَيُكَبِّرُ سَبْعَ مِرَارٍ ثَلَاثًا يُكَبِّرُ ثُمَّ يَقُولُ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ ‏","","",""]];
